package com.imageseal.controller;
import com.imageseal.entity.*;import com.imageseal.repository.*;import com.imageseal.security.UserPrincipal;import com.imageseal.service.ImageStorageService;import com.imageseal.service.ImageValidationService;import com.imageseal.service.Sha256Service;
import jakarta.transaction.Transactional;import org.springframework.core.io.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.security.*;import java.time.Instant;import java.util.*;

@RestController @RequestMapping("/api") public class ImageController {
 private final ImageRepository images;private final VerificationRepository verifications;private final UserRepository users;private final ImageVersionRepository versions;private final DuplicateUploadRepository duplicates;private final AuditLogRepository audit;private final ImageStorageService storage;private final ImageValidationService validator;private final Sha256Service sha256;
 public ImageController(ImageRepository i,VerificationRepository v,UserRepository u,ImageVersionRepository versions,DuplicateUploadRepository duplicates,AuditLogRepository audit,ImageStorageService storage,ImageValidationService validator,Sha256Service sha256){images=i;verifications=v;users=u;this.versions=versions;this.duplicates=duplicates;this.audit=audit;this.storage=storage;this.validator=validator;this.sha256=sha256;}
 private AppUser owner(UserPrincipal p){return users.findById(p.id()).orElseThrow();}
 private Map<String,Object> dto(ImageRecord i){return Map.of("id",i.getId(),"name",i.getName(),"mime_type",i.getMimeType(),"file_size",i.getFileSize(),"storage_path",i.getId(),"sha256",i.getSha256(),"created_at",i.getCreatedAt(),"width",0,"height",0,"url","/api/images/"+i.getId()+"/file");}
 private void validate(MultipartFile file)throws Exception{validator.validate(file);}
 @GetMapping("/images") public List<Map<String,Object>> all(@AuthenticationPrincipal UserPrincipal p){return images.findAllByOwnerIdOrderByCreatedAtDesc(p.id()).stream().map(this::dto).toList();}
 @GetMapping("/images/{id}") public Map<String,Object> one(@PathVariable String id,@AuthenticationPrincipal UserPrincipal p){return dto(images.findByIdAndOwnerId(id,p.id()).orElseThrow(()->new NoSuchElementException("Image not found")));}
 @GetMapping("/images/{id}/file") public ResponseEntity<Resource> file(@PathVariable String id,@AuthenticationPrincipal UserPrincipal p)throws Exception{ImageRecord i=images.findByIdAndOwnerId(id,p.id()).orElseThrow(()->new NoSuchElementException("Image not found"));return ResponseEntity.ok().contentType(MediaType.parseMediaType(i.getMimeType())).header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename=\""+i.getName().replace("\"","")+"\"").body(new ByteArrayResource(storage.read(i.getStoragePath())));}
 @GetMapping("/files/{id}") public ResponseEntity<Resource> storedFile(@PathVariable String id,@AuthenticationPrincipal UserPrincipal p)throws Exception{var image=images.findByIdAndOwnerId(id,p.id());if(image.isPresent())return file(id,p);var check=verifications.findById(id).filter(v->v.getOwner().getId().equals(p.id()));if(check.isPresent()){var v=check.get();return ResponseEntity.ok().contentType(MediaType.parseMediaType(v.getCheckMimeType())).header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename=\""+v.getCheckName().replace("\"","")+"\"").body(new ByteArrayResource(storage.read(v.getCheckStoragePath())));}var version=versions.findByIdAndOwnerId(id,p.id()).orElseThrow(()->new NoSuchElementException("Image not found"));return ResponseEntity.ok().contentType(MediaType.parseMediaType(version.getMimeType())).header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename=\""+version.getName().replace("\"","")+"\"").body(new ByteArrayResource(storage.read(version.getStoragePath())));}
 @PostMapping(value="/images",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Map<String,Object> upload(@RequestPart("file") MultipartFile file,@AuthenticationPrincipal UserPrincipal p)throws Exception{validate(file);byte[] bytes=file.getBytes();String sha=sha256.hash(bytes);String filename=Path.of(Objects.requireNonNullElse(file.getOriginalFilename(),"image")).getFileName().toString();var duplicate=images.findFirstByOwnerIdAndSha256(p.id(),sha);if(duplicate.isPresent()){duplicates.save(new DuplicateUpload(owner(p),duplicate.get(),filename,sha));Map<String,Object> result=new HashMap<>(dto(duplicate.get()));result.put("duplicate",true);audit.save(new AuditLog(owner(p),"DUPLICATE_UPLOAD",duplicate.get().getId()));return result;}String id=UUID.randomUUID().toString();String ext="image/png".equals(file.getContentType())?".png":".jpg";String rel=p.id()+"/"+id+ext;storage.write(rel,bytes);try{ImageRecord saved=images.save(new ImageRecord(owner(p),filename,file.getContentType(),file.getSize(),rel,sha));audit.save(new AuditLog(owner(p),"IMAGE_UPLOAD",saved.getId()));Map<String,Object> result=new HashMap<>(dto(saved));result.put("duplicate",false);return result;}catch(Exception e){storage.delete(rel);throw e;}}
 @GetMapping("/duplicates") public List<Map<String,Object>> duplicateUploads(@AuthenticationPrincipal UserPrincipal p){return duplicates.findAllByOwnerIdOrderByCreatedAtDesc(p.id()).stream().map(d->Map.<String,Object>of("id",d.getId(),"upload_name",d.getUploadName(),"sha256",d.getSha256(),"created_at",d.getCreatedAt())).toList();}
 @DeleteMapping("/images/{id}") @Transactional public ResponseEntity<Void> delete(@PathVariable String id,@AuthenticationPrincipal UserPrincipal p)throws Exception{ImageRecord i=images.findByIdAndOwnerId(id,p.id()).orElseThrow(()->new NoSuchElementException("Image not found"));for(VerificationRecord v:verifications.findAllByOwnerIdOrderByCreatedAtDesc(p.id()))if(v.getImage().getId().equals(id))storage.delete(v.getCheckStoragePath());verifications.deleteAllByImageId(id);for(ImageVersion v:versions.findAllByOriginalIdAndOwnerIdOrderByVersionNumberAsc(id,p.id())){storage.delete(v.getStoragePath());versions.delete(v);}duplicates.deleteAllByExistingImageId(id);storage.delete(i.getStoragePath());images.delete(i);audit.save(new AuditLog(owner(p),"IMAGE_DELETE",id));return ResponseEntity.noContent().build();}
 @PostMapping(value="/images/{id}/verify",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @Transactional public Map<String,Object> verify(@PathVariable String id,@RequestPart("file") MultipartFile file,@AuthenticationPrincipal UserPrincipal p)throws Exception{validate(file);ImageRecord i=images.findByIdAndOwnerId(id,p.id()).orElseThrow(()->new NoSuchElementException("Image not found"));byte[] bytes=file.getBytes();String check=sha256.hash(bytes);boolean match=sha256.matches(i.getSha256(),check);String verificationId=UUID.randomUUID().toString();String mime=file.getContentType();String rel=p.id()+"/checks/"+verificationId+("image/png".equals(mime)?".png":".jpg");storage.write(rel,bytes);try{VerificationRecord v=verifications.save(new VerificationRecord(owner(p),i,Objects.requireNonNullElse(file.getOriginalFilename(),"check"),rel,mime,i.getSha256(),check,match));audit.save(new AuditLog(owner(p),"IMAGE_VERIFY",i.getId()));return Map.of("id",v.getId(),"original_sha256",i.getSha256(),"check_sha256",check,"matched",match,"check_name",v.getCheckName(),"check_storage_path",v.getId(),"created_at",v.getCreatedAt());}catch(Exception e){storage.delete(rel);throw e;}}
 @GetMapping("/verifications") @Transactional public List<Map<String,Object>> history(@AuthenticationPrincipal UserPrincipal p){return verifications.findAllByOwnerIdOrderByCreatedAtDesc(p.id()).stream().map(v->Map.<String,Object>of("id",v.getId(),"original_image_id",v.getImage().getId(),"original_name",v.getImage().getName(),"original_sha256",v.getOriginalSha256(),"check_name",v.getCheckName(),"check_storage_path",v.getId(),"check_sha256",v.getCheckSha256(),"matched",v.isMatched(),"created_at",v.getCreatedAt())).toList();}
 @DeleteMapping("/verifications/{id}") @Transactional public ResponseEntity<Void> deleteVerification(@PathVariable String id,@AuthenticationPrincipal UserPrincipal p)throws Exception{VerificationRecord v=verifications.findById(id).filter(row->row.getOwner().getId().equals(p.id())).orElseThrow(()->new NoSuchElementException("Verification not found"));storage.delete(v.getCheckStoragePath());verifications.delete(v);return ResponseEntity.noContent().build();}
 @DeleteMapping("/verifications") @Transactional public ResponseEntity<Void> clearVerifications(@AuthenticationPrincipal UserPrincipal p)throws Exception{for(VerificationRecord v:verifications.findAllByOwnerIdOrderByCreatedAtDesc(p.id()))storage.delete(v.getCheckStoragePath());verifications.deleteAll(verifications.findAllByOwnerIdOrderByCreatedAtDesc(p.id()));return ResponseEntity.noContent().build();}
}
